# Azure blog post on MLPerf Inference v6.1, held against the v5.0, v5.1, v6.0 and v6.1 result files. python3 -I check_claims_azure_v61.py
import json,hashlib
FILES=['raw/inf_5.0.json','raw/inf_5.1.json','raw/inf_6.0.json','raw/inf_6.1.json','raw/older_rounds_systems.json']; RAW={f:open(f,'rb').read() for f in FILES}
V5=json.loads(RAW[FILES[0]]); V51=json.loads(RAW[FILES[1]]); V0=json.loads(RAW[FILES[2]]); B=list(json.loads(RAW[FILES[3]]).values()); OLD=json.loads(RAW[FILES[4]]); s=str; pc=lambda x,y:100*(x/y-1)
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
AZ=[x for x in B if x['Organization']=='Azure']
def az(g,n,sc): r=[x for x in AZ if g in x['SystemName'] and x['total_accelerators']==n and x['Scenario']==sc]; assert len(r)==1,(g,n,sc); return r[0]
def acc(x):
    a=s(x['accelerator_model_name']); return 'GB300' if 'GB300' in a else 'GB200' if 'GB200' in a else a
def ds(sc,f=lambda x:True,av=True): return sorted([x for x in B if x['Division']=='closed' and (x['Availability']=='available' or not av) and x['Model']=='deepseek-r1' and x['Scenario']==sc and f(x)],key=lambda x:-x['Result'])
AZL=[]
a1=(az('GB200',72,'Offline')['number_of_nodes'],az('GB200',288,'Offline')['number_of_nodes'],az('GB300',72,'Offline')['number_of_nodes'])
AZL.append(mk('AZ1','Azure submitted GB200 results at 18-node (1-rack) and 72-node (4-rack) scale, and GB300 results at 18 nodes (1 rack)','Azure entries in the v6.1 file, nodes and accelerators','GB200 at 18 and 72 nodes, GB300 at 18 nodes',f'GB200 {az("GB200",72,"Offline")["total_accelerators"]} accelerators on {a1[0]} nodes and {az("GB200",288,"Offline")["total_accelerators"]} accelerators on {a1[1]} nodes; GB300 {az("GB300",72,"Offline")["total_accelerators"]} accelerators on {a1[2]} nodes','CONSISTENT' if a1==(18,72,18) else 'BELOW',''))
vals=[('GB300',72,'Interactive',260098),('GB300',72,'Offline',661143),('GB300',72,'Server',589391),('GB200',72,'Offline',542075),('GB200',72,'Server',426796),('GB200',288,'Offline',2091190),('GB200',288,'Server',1598510)]
ok=all(round(az(g,n,sc)['Result'])==v for g,n,sc,v in vals)
AZL.append(mk('AZ2','Results table in the post, seven DeepSeek-R1 throughput values for three Azure platforms','Azure DeepSeek-R1 entries in the v6.1 file','seven table values in tokens/s',', '.join(f'{g}/{n} {sc} {az(g,n,sc)["Result"]:,.0f}' for g,n,sc,v in vals),'CONSISTENT' if ok else 'BELOW','Every table value matches the file to the digit printed.' if ok else ''))
i3=ds('Interactive',lambda x:acc(x)=='GB300')
AZL.append(mk('AZ3','Azure achieved the highest reported Interactive score on GB300 NVL72','closed available v6.1 DeepSeek-R1 Interactive entries on GB300','highest Interactive on GB300',f'top {i3[0]["Organization"]} {i3[0]["Result"]:,.0f}, next {i3[1]["Organization"]} {i3[1]["Result"]:,.0f}','CONSISTENT' if i3[0]['Organization']=='Azure' else 'BELOW',''))
g1,g1o=ds('Server',lambda x:acc(x)=='GB200' and x['total_accelerators']==72),ds('Offline',lambda x:acc(x)=='GB200' and x['total_accelerators']==72); g4,g4o=ds('Server',lambda x:acc(x)=='GB200' and x['total_accelerators']==288),ds('Offline',lambda x:acc(x)=='GB200' and x['total_accelerators']==288)
AZL.append(mk('AZ4','the highest reported Server and Offline scores on GB200 NVL72 at both 1- and 4-rack scale','closed available v6.1 DeepSeek-R1 entries on 72 and 288 GB200 accelerators','highest Server and Offline at one rack and four racks',f'one rack Server top {g1[0]["Organization"]} of {len(g1)}, Offline top {g1o[0]["Organization"]} of {len(g1o)}; four racks Server {len(g4)} entry ({g4[0]["Organization"]}), Offline {len(g4o)} entry','CONSISTENT' if g1[0]['Organization']=='Azure' and g1o[0]['Organization']=='Azure' and g4[0]['Organization']=='Azure' else 'BELOW','Azure is the only entry at four racks, so that part holds by the absence of others.'))
b3s=ds('Server',lambda x:acc(x)=='GB300' and x['total_accelerators']==72); b3o=ds('Offline',lambda x:acc(x)=='GB300' and x['total_accelerators']==72); a3s,a3o=az('GB300',72,'Server')['Result'],az('GB300',72,'Offline')['Result']
allS,allO=ds('Server')[0],ds('Offline')[0]
AZL.append(mk('AZ5','Azure\'s GB300 submission achieved 97.7% of the best reported Server performance and 95.8% of the best reported Offline performance','Azure GB300 entry against the best 72 GPU GB300 DeepSeek-R1 entry, and against the best entry of any kind','97.7% of best Server, 95.8% of best Offline',f'against the best 72 GPU GB300 entry ({b3s[0]["Organization"]} {b3s[0]["Result"]:,.0f} and {b3o[0]["Organization"]} {b3o[0]["Result"]:,.0f}): {100*a3s/b3s[0]["Result"]:.1f}% and {100*a3o/b3o[0]["Result"]:.1f}%. Against the best entry of any kind ({allS["Organization"]} {allS["Result"]:,.0f} Server, {allO["Organization"]} {allO["Result"]:,.0f} Offline): {100*a3s/allS["Result"]:.1f}% and {100*a3o/allO["Result"]:.1f}%','CONSISTENT' if (round(100*a3s/b3s[0]['Result'],1),round(100*a3o/b3o[0]['Result'],1))==(97.7,95.8) else 'BELOW','Our rule: best reported means the best 72 GPU GB300 entry. Against Azure\'s own 288 GPU GB200 entry the shares are about 37% and 32%.'))
ia=ds('Interactive',av=False)
AZL.append(mk('AZ6','maintaining the highest Interactive performance among all reported submissions','closed v6.1 DeepSeek-R1 Interactive entries, all availability categories','highest Interactive among all submissions',f'all categories: top {ia[0]["Organization"]} {ia[0]["Result"]:,.0f} ({ia[0]["Availability"]}, {s(ia[0]["accelerator_model_name"])}), then {ia[1]["Organization"]} {ia[1]["Result"]:,.0f}; available only: top {ds("Interactive")[0]["Organization"]}','CONSISTENT' if ia[0]['Organization']=='Azure' else 'BELOW','The higher entry is a preview category submission. Among available entries Azure is first.'))
earlier=[(n,x['ID'],x.get('Total Accelerators') or x.get('a#')) for n,L in(('v5.0',V5),('v5.1',V51),('v6.0',V0)) for x in L if x['Submitter']=='Azure' and x['Scenario'] in('Offline','Server')][:3]
big=[e for e in earlier if int(e[2] or 0)>=72]
old_az=[(r,x['path'].split('/')[-1],x['nodes'],x['accelerators_per_node']) for r,v in OLD.items() for x in v['selected_systems'] if x['submitter']=='Azure']
AZL.append(mk('AZ7','marking our first rack-scale and cross-rack MLPerf Inference submissions','Azure entries in the v5.0, v5.1 and v6.0 files, accelerator counts','first rack-scale submission',f'earlier Azure entries: {sorted({(e[0],e[1],e[2]) for e in earlier})}; system files in v3.1 and v4.0: {old_az}; 72 or more accelerators before v6.1: {len(big)}','CONSISTENT' if not big and all(int(n or 0)*int(a or 0)<=8 for r,f,n,a in old_az) else 'BELOW','Rounds before v5.0 were read from system description files, which show one node of 2 to 8 accelerators.'))
json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=AZL),open('claims_azure_v61.json','w'),indent=1)
for c in AZL: print(c['id'],c['outcome'],'|',c['stated'][:48],'|',c['delivered'][:300])
